package nativegen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
)

const goHeader = "// Code generated by mygo generate from the interfaces of the native module. DO NOT EDIT.\n"

// SourceLine is the line of a generated file that names the declarations
// it came from, which `mygo build` compares with the package's.
func SourceLine(hash string) string { return "mygo:native " + Version + " " + hash }

// GenerateGo writes the Go side: the module's description, a constructor
// per entry point and the values that call the implementation.
func GenerateGo(m *Module, minMacOS string) ([]byte, error) {
	var b bytes.Buffer
	g := &goGen{m: m, b: &b}
	fmt.Fprintf(&b, "%s// %s\n\npackage %s\n\nIMPORTS\n", goHeader, SourceLine(m.Hash), m.Package)
	var errs []string
	for _, e := range m.Errors {
		errs = append(errs, e.Name)
	}
	fmt.Fprintf(&b, `
// _module is the module's description, for package native.
var _module = &native.Module{Name: %q, Symbol: %q, MinMacOS: %q, Dir: _dir(), Errors: []*native.Error{%s}}

// _dir returns the package's directory when the binary knows it, where
// mygo generate builds the implementation for go test and go run.
func _dir() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok || !filepath.IsAbs(file) {
		return ""
	}
	return filepath.Dir(file)
}
`, m.Name, m.Package, minMacOS, strings.Join(errs, ", "))
	for _, it := range m.Interfaces {
		if it.ByGo {
			g.dispatch(it)
		} else {
			g.proxy(it)
		}
	}
	out := b.String()
	var imports []string
	for path, used := range map[string]bool{
		"github.com/egoist/mygo/native": true,
		"path/filepath":                 true,
		"runtime":                       true,
		"context":                       strings.Contains(out, "context."),
		"iter":                          strings.Contains(out, "iter."),
		"fmt":                           strings.Contains(out, "fmt."),
		"io":                            strings.Contains(out, "io.Closer"),
		"time":                          strings.Contains(out, "time."),
		mygoPath:                        strings.Contains(out, "*mygo."),
		uiPath:                          strings.Contains(out, "ui.Rect"),
	} {
		if used {
			imports = append(imports, fmt.Sprintf("%q", path))
		}
	}
	sort.Strings(imports)
	var std, other []string
	for _, imp := range imports {
		if strings.Contains(imp, ".") {
			other = append(other, imp)
		} else {
			std = append(std, imp)
		}
	}
	out = strings.Replace(out, "IMPORTS", "import (\n"+strings.Join(std, "\n")+"\n\n"+strings.Join(other, "\n")+"\n)", 1)
	src, err := format.Source([]byte(out))
	if err != nil {
		return nil, fmt.Errorf("nativegen: formatting the Go of %s: %v\n%s", m.Package, err, out)
	}
	return src, nil
}

type goGen struct {
	m *Module
	b *bytes.Buffer
}

func (g *goGen) p(format string, args ...any) { fmt.Fprintf(g.b, format, args...) }

func proxyName(it *Interface) string { return "_" + it.Name }

func flagsOf(mt bool) string {
	if mt {
		return "native.MainThread"
	}
	return "0"
}

// signature writes a method's Go signature, as the interface declares it.
func signature(m *Method) string {
	var ps []string
	if m.Ctx {
		ps = append(ps, "ctx context.Context")
	}
	for _, p := range m.Params {
		ps = append(ps, p.Name+" "+p.Type.Go)
	}
	res := ""
	switch {
	case m.Stream == 1:
		res = " iter.Seq[" + m.Result.Go + "]"
	case m.Stream == 2:
		res = " iter.Seq2[" + m.Result.Go + ", error]"
	case m.Closer:
		res = " io.Closer"
	case m.Result != nil && m.Err:
		res = " (" + m.Result.Go + ", error)"
	case m.Result != nil:
		res = " " + m.Result.Go
	case m.Err:
		res = " error"
	}
	return m.Name + "(" + strings.Join(ps, ", ") + ")" + res
}

func (g *goGen) proxy(it *Interface) {
	name := proxyName(it)
	if it.Entry {
		g.p("\n// New%s makes the implementation of %s on this platform. It returns\n// errors.ErrUnsupported where the module has none, or the system lacks\n// what it needs.\nfunc New%s() (%s, error) {\n", it.Name, it.Name, it.Name, it.Name)
		g.p("\to, err := _module.New(%q, %s)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &%s{o}, nil\n}\n", it.Name, flagsOf(it.MainThread), name)
	}
	g.p("\n// %s calls the platform's implementation of %s.\ntype %s struct{ o *native.Object }\n", name, it.Name, name)
	g.p("\n// NativeObject returns the platform's object.\nfunc (x *%s) NativeObject() *native.Object { return x.o }\n", name)
	g.p("\n// %s wraps a handle of the platform's, or returns nil.\nfunc _wrap%s(h uint64) %s {\n\tif h == 0 {\n\t\treturn nil\n\t}\n\treturn &%s{_module.Object(h)}\n}\n", "_wrap"+it.Name, it.Name, it.Name, name)
	for _, m := range it.Methods {
		g.method(it, m)
	}
}

// argExprs returns the expressions of a call's arguments, with the
// statements that prepare them and the handles of its callbacks.
func (g *goGen) argExprs(m *Method) (pre []string, args []string, funcs []string) {
	for i, p := range m.Params {
		switch p.Type.Kind {
		case Func:
			v := fmt.Sprintf("_f%d", i)
			pre = append(pre, fmt.Sprintf("var %s uint64\n\tif %s != nil {\n\t\t%s = native.Func(%s, %v)\n\t}", v, p.Name, v, g.funcWrapper(p.Name, p.Type), notifies(p.Type)))
			args = append(args, v)
			funcs = append(funcs, v)
		case InterfaceType:
			if p.Type.Iface.ByGo {
				v := fmt.Sprintf("_g%d", i)
				pre = append(pre, fmt.Sprintf("var %s uint64\n\tif %s != nil {\n\t\t%s = native.Export(_module, %s, func(ctx context.Context, m int, a native.Args) (any, error) { return _dispatch%s(%s, ctx, m, a) })\n\t}", v, p.Name, v, p.Name, p.Type.Iface.Name, p.Name))
				args = append(args, v)
				funcs = append(funcs, v)
			} else {
				args = append(args, "native.HandleOf("+p.Name+")")
			}
		case Window:
			args = append(args, "native.WindowHandle("+p.Name+")")
		default:
			args = append(args, p.Name)
		}
	}
	return
}

func notifies(t *Type) bool { return t.Result == nil && !t.Err }

// funcWrapper returns a function of native.Args that calls the Go
// function fn, of type t.
func (g *goGen) funcWrapper(fn string, t *Type) string {
	var b strings.Builder
	b.WriteString("func(a native.Args) (any, error) {\n")
	var call []string
	for i, p := range t.Params {
		fmt.Fprintf(&b, "var p%d %s\nif err := a.Decode(%d, &p%d); err != nil {\nreturn nil, err\n}\n", i, p.Type.Go, i, i)
		call = append(call, fmt.Sprintf("p%d", i))
	}
	c := fn + "(" + strings.Join(call, ", ") + ")"
	switch {
	case t.Result != nil && t.Err:
		b.WriteString("return " + c + "\n")
	case t.Result != nil:
		b.WriteString("return " + c + ", nil\n")
	case t.Err:
		b.WriteString("return nil, " + c + "\n")
	default:
		b.WriteString(c + "\nreturn nil, nil\n")
	}
	b.WriteString("}")
	return b.String()
}

func (g *goGen) method(it *Interface, m *Method) {
	name := proxyName(it)
	g.p("\nfunc (x *%s) %s {\n", name, signature(m))
	sym := it.Name + "_" + m.Name
	flags := flagsOf(m.MainThread)
	if m.Close {
		g.p("\treturn x.o.Close()\n}\n")
		return
	}
	pre, args, funcs := g.argExprs(m)
	for _, s := range pre {
		g.p("\t%s\n", s)
	}
	for _, p := range m.Params {
		if p.Type.Kind == Buffer {
			g.p("\tdefer runtime.KeepAlive(%s)\n", p.Name)
		}
	}
	argList := "nil"
	if len(args) > 0 {
		argList = "[]any{" + strings.Join(args, ", ") + "}"
	}
	forget := ""
	if len(funcs) > 0 {
		forget = "\t\tnative.Forget(" + strings.Join(funcs, ", ") + ")\n"
	}
	switch {
	case m.Stream != 0:
		var expr string
		if m.Result.Kind == InterfaceType {
			expr = fmt.Sprintf("native.StreamMap(ctx, x.o, %q, %s, %s, _wrap%s)", sym, flags, argList, m.Result.Iface.Name)
		} else {
			expr = fmt.Sprintf("native.Stream[%s](ctx, x.o, %q, %s, %s)", m.Result.Go, sym, flags, argList)
		}
		if m.Stream == 1 {
			expr = "native.Seq(" + expr + ")"
		}
		g.p("\treturn %s\n}\n", expr)
		return
	case m.Closer:
		g.p("\treturn x.o.Subscribe(%q, %s, %s%s)\n}\n", sym, flags, argList, prefixComma(funcs))
		return
	}
	callFn := fmt.Sprintf("x.o.Call(%q, %s, %s, ", sym, flags, argList)
	if m.Ctx {
		callFn = fmt.Sprintf("x.o.CallContext(ctx, %q, %s, %s, ", sym, flags, argList)
	}
	switch {
	case m.Result == nil:
		g.p("\terr := %snil)\n", callFn)
		if forget != "" {
			g.p("\tif err != nil {\n%s\t}\n", forget)
		}
		if m.Err {
			g.p("\treturn err\n")
		}
	case m.Result.Kind == InterfaceType:
		g.p("\tvar h uint64\n\terr := %s&h)\n", callFn)
		g.p("\tif err != nil {\n%s", forget)
		if m.Err {
			g.p("\t\treturn nil, err\n\t}\n\treturn _wrap%s(h), nil\n", m.Result.Iface.Name)
		} else {
			g.p("\t\treturn nil\n\t}\n\treturn _wrap%s(h)\n", m.Result.Iface.Name)
		}
	default:
		g.p("\tvar r %s\n\terr := %s&r)\n", m.Result.Go, callFn)
		if forget != "" {
			g.p("\tif err != nil {\n%s\t}\n", forget)
		}
		if m.Err {
			g.p("\treturn r, err\n")
		} else {
			g.p("\t_ = err\n\treturn r\n")
		}
	}
	g.p("}\n")
}

func prefixComma(s []string) string {
	if len(s) == 0 {
		return ""
	}
	return ", " + strings.Join(s, ", ")
}

// dispatch writes the function the platform calls the methods of a Go
// value of an interface Go implements through.
func (g *goGen) dispatch(it *Interface) {
	g.p("\n// _dispatch%s calls the method number m of v for the platform.\nfunc _dispatch%s(v %s, ctx context.Context, m int, a native.Args) (any, error) {\n\tswitch m {\n", it.Name, it.Name, it.Name)
	for i, m := range it.Methods {
		g.p("\tcase %d:\n", i)
		var call []string
		if m.Ctx {
			call = append(call, "ctx")
		}
		for j, p := range m.Params {
			g.p("\t\tvar p%d %s\n\t\tif err := a.Decode(%d, &p%d); err != nil {\n\t\t\treturn nil, err\n\t\t}\n", j, p.Type.Go, j, j)
			call = append(call, fmt.Sprintf("p%d", j))
		}
		c := "v." + m.Name + "(" + strings.Join(call, ", ") + ")"
		switch {
		case m.Result != nil && m.Err:
			g.p("\t\treturn %s\n", c)
		case m.Result != nil:
			g.p("\t\treturn %s, nil\n", c)
		case m.Err:
			g.p("\t\treturn nil, %s\n", c)
		default:
			g.p("\t\t%s\n\t\treturn nil, nil\n", c)
		}
	}
	g.p("\t}\n\treturn nil, fmt.Errorf(\"native: %s has no method %%d\", m)\n}\n", it.Name)
}
